#[test]
fn sqlite_snapshot_semio_kit_manual_native_child_and_link_fields_are_literal(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for id in f["literalChildIds"].as_array().unwrap(){let id=id.as_str().unwrap();let target=semio_framework_artifact_reference::ArtifactRef{artifact_id:id.into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()}};let child=store::os_store::artifact_child::ArtifactChild::<SemioObjectSnapshot>::new(id.into(),target.clone());let text=enc_child(&child);let restored:store::os_store::artifact_child::ArtifactChild<SemioObjectSnapshot>=dec_child(&text).unwrap();assert_eq!(restored.child_id,id);assert_eq!(restored.target,target);let mut bytes=Vec::new();write_child(&mut bytes,&child);let restored:store::os_store::artifact_child::ArtifactChild<SemioObjectSnapshot>=read_child(&mut store::ByteReader::new(&bytes)).unwrap();assert_eq!(restored.child_id,id);assert_eq!(restored.target,target);let link=store::ArtifactLink{target:target.clone(),role:"".into(),pin:store::LinkPin::Head};assert_eq!(dec_link(&enc_link(&link)).unwrap(),link);let mut bytes=Vec::new();write_link(&mut bytes,&link);assert_eq!(read_link(&mut store::ByteReader::new(&bytes)).unwrap(),link);}}

