#[test]
fn sqlite_snapshot_semio_kit_rejects_design_reference_identity_pin_shape_and_limits(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_kit_connection").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_kit_piece").unwrap().rows[0].values[4]=SqliteValue::Integer(999),2=>db.table_mut("semio_kit_reference").unwrap().rows[0].values[2]=SqliteValue::Text("foreign.artifact".into()),3=>db.table_mut("semio_kit_representation").unwrap().rows[0].values[6]=SqliteValue::Text("unexpected".into()),4=>db.table_mut("semio_kit_blob").unwrap().rows[0].values[2]=SqliteValue::Text("18446744073709551616".into()),_=>db.table_mut("semio_kit_piece").unwrap().rows[0].values[2]=SqliteValue::Integer(99)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| fixture().to_sqlite_database(control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| SemioKitSnapshot::from_sqlite_database(&original,control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|false, |control| fixture().to_sqlite_database(control)).is_err());}
#[test]
fn sqlite_snapshot_semio_kit_independent_connection_query_and_pin_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT a.native_id a,b.native_id b FROM semio_kit_connection JOIN semio_kit_piece a ON a.id=connecting_piece_id JOIN semio_kit_piece b ON b.id=connected_piece_id').get();if(r.a!=='left'||r.b!=='right'||db.query('SELECT size FROM semio_kit_blob').get().size!=='18446744073709551615')throw Error('design/wide blob');db.query(\"UPDATE semio_kit_representation SET checkpoint_id='independently edited' WHERE pin_kind='checkpoint'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.representations[1].pin=store::LinkPin::Checkpoint{id:"independently edited".into()};assert_eq!(restored,expected);}

